    string s;
    int k;
    cin >> s >> k;
    vector<int> ones;
    for (int i = 0; i < (int)s.size(); i++)
        if (s[i] == '1') ones.push_back(i);
    // Each window of k consecutive ones gives the shortest candidate covering them.
    string best;
    bool found = false;
    for (int i = 0; i + k <= (int)ones.size(); i++) {
        string z = s.substr(ones[i], ones[i + k - 1] - ones[i] + 1);
