import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int k = sc.nextInt();
        List<Integer> ones = new ArrayList<>();
        for (int i = 0; i < s.length(); i++)
            if (s.charAt(i) == '1') ones.add(i);
        // Each window of k consecutive ones gives the shortest candidate covering them.
        String best = null;
        for (int i = 0; i + k <= ones.size(); i++) {
            String z = s.substring(ones.get(i), ones.get(i + k - 1) + 1);
            if (best == null || z.length() < best.length() || (z.length() == best.length() && z.compareTo(best) < 0)) best = z;
        }
        System.out.println(best);
    }
}

package main

import "fmt"

func main() {
	var s string
	var k int
	fmt.Scan(&s, &k)
	ones := []int{}
	for i := 0; i < len(s); i++ {
		if s[i] == '1' {
			ones = append(ones, i)
		}
	}
	// Each window of k consecutive ones gives the shortest candidate covering them.
	best, found := "", false
	for i := 0; i+k <= len(ones); i++ {
		z := s[ones[i] : ones[i+k-1]+1]
		if !found || len(z) < len(best) || (len(z) == len(best) && z < best) {
			best, found = z, true
		}
	}
	fmt.Println(best)
}
